								local v26

								if wingPhase and i >= coconutForms.WingStart and i < coconutForms.WingStart + 12 then
									local n50 = i - coconutForms.WingStart
									local n51

									if n50 < 6 then
										n51 = -1
									else
										n51 = 1
									end

									local n52 = n50 % 6 + 1
									local n53 = (n52 - 1) * coconutForms.WingSpacing
									local v27 = coconutForms.WingRipple[n52]

