									else
										v26 = n40
									end

									local cframe = CFrame.new
									local n54 = n51 * (0.55 + n53)
									local n55 = n53 / 1.1
									local n56

									if flight then
										n56 = 0.1
									else
										n56 = 0.16
									end

									local v28 = cframe(n54, 0.05 - n55 * n56 + v27, n53 / 1.1 * 0.06 + v27 * 0.35)
