			end
			local id = arg.Id or arg.id
			local num = tonumber(arg.Playing or arg.playing)
			local num2 = tonumber(arg.MaxPlayers or arg.maxPlayers)
			if type(id) ~= "string" or not num or not num2 or num2 <= 0 then
