			end

			return {
				Id = id,
				Playing = math.max(0, num),
				MaxPlayers = num2,
				Ping = tonumber(arg.Ping or arg.ping),
				FPS = tonumber(arg.FPS or arg.fps),
			}
		end

		tbl12.IsServerHopCandidate = function(arg, arg2)
			if arg.Id == jobId or tbl7.ServerHop.Rejected[arg.Id] then
