		v20:AddDivider("Grabbing")

		v20:AddDropdown("GrabTypeDropdown", {
			Values = { "Aura", "Grab", "None" },
			Default = table.find({ "Aura", "Grab", "None" }, toysAuraSettings.OwnType) or 1,
