					tbl12.DestroyObject(v25)
					v24:ChangeDescription("Destroyed " .. i .. "/" .. #tbl16 .. " toys")
				end

				while tbl9.DestroyThread and not flag11 do
					RunService.Heartbeat:Wait()
				end

				tbl7.States.DestroyingToys = false

				task.delay(0.25, function()
					v24:Destroy()
				end)
			end,
		})
	end

